	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+0(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+16(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+32(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+48(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	CMPQ CX, $10
	JE v256_blk_vex_final
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+64(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+80(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
v256_blk_vex_final:
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VAESENCLAST X4, X0, X0
	VAESENCLAST X5, X1, X1
	VMOVDQU X0, 0(DI)
	VMOVDQU X1, 16(DI)
	VPXOR X0, X0, X0
	VPXOR X1, X1, X1
	VPXOR X2, X2, X2
	VPXOR X3, X3, X3
	VPXOR X4, X4, X4
	VPXOR X5, X5, X5
	VPXOR X6, X6, X6
	VPXOR X7, X7, X7
	VPXOR X8, X8, X8
	VPXOR X9, X9, X9
	VPXOR X10, X10, X10
	VPXOR X11, X11, X11
	XORQ DI, DI
	XORQ SI, SI
	XORQ DX, DX
